const result = $input.first().json;
if (result.status !== 'succeeded') throw new Error('BeatAPI TikTok video search did not succeed.');
if (!Array.isArray(result.items)) throw new Error('No projected TikTok video items were returned. Inspect the Social Data response.');
const records = result.items.slice(0, 12).map((entry) => {
const p = entry.aweme_info ?? entry;
const id = String(p.aweme_id ?? p.id ?? '');
const author = String(p.author?.unique_id ?? p.author?.username ?? '');
const url = author && id ? 'https://www.tiktok.com/@' + author + '/video/' + id : (p.share_url ?? '');
const description = String(p.desc ?? p.description ?? '').slice(0, 1300);
return { id, url, author, description, views: p.statistics?.play_count ?? null, likes: p.statistics?.digg_count ?? null, comments: p.statistics?.comment_count ?? null, created_at: p.create_time ?? null };
}).filter((p) => (p.id || p.url) && p.description);
if (!records.length) throw new Error('No identifiable public TikTok videos were found for this keyword. Try another keyword or inspect the response.');
return [{ json: { source: 'TikTok public keyword video search', source_count: records.length, items_total: result.items_total ?? null, preview_truncated: Boolean(result.truncated || (typeof result.items_total === 'number' && result.items_total > records.length)), request_ids: result.request_id ? [result.request_id] : [], prompt: JSON.stringify({ keyword: $('Configure Inputs').first().json.keyword, records }) } }];

const answer = $input.first().json.choices?.[0]?.message?.content;
if (!answer) throw new Error('The text model returned no message content.');
const evidence = $('Prepare Evidence').first().json;
return [{ json: { summary: answer, source: evidence.source, source_count: evidence.source_count, items_total: evidence.items_total, preview_truncated: evidence.preview_truncated, request_ids: evidence.request_ids } }];
